def consume_tokens(bucket: dict, cost: int, capacity: int = 100) -> bool:
    available = bucket.get('tokens', capacity)
    if cost < 0:
        return False
    if available < cost:
        return False
    bucket['tokens'] = available - cost
    return True

files.api.py:
from rate_limiter import consume_tokens

def dispatch_batch(bucket: dict, items: list[str], capacity: int = 100) -> dict:
    if not consume_tokens(bucket, len(items), capacity):
        return {'ok': False, 'head': None, 'dispatched': 0}
    bucket['batches_sent'] = bucket.get('batches_sent', 0) + 1
    return {'ok': True, 'head': items[0], 'dispatched': len(items)}

